163	    /**
164	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
165	     */
166	    @Transient
167	    public String getDisplayName() {
168	        return this.getLastName() + ", " + this.getFirstName();
169	    }
170	
171	    /**
172	     * The owner's initials: the upper-cased first letters of the first and last name,
173	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
174	     */
175	    @Transient
176	    public String getInitials() {
177	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
178	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
179	    }
180	
181	    /**
182	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
183	     * the last two digits of the registration date year (e.g. {@code 'SMI-0007-M26'}). Derived from
184	     * the owner's own fields; {@code null} until both the customer code and registration date are set.
185	     */
186	    @Transient
187	    public String getMembershipNumber() {
188	        if (this.customerCode == null || this.registrationDate == null) {
189	            return null;
190	        }
191	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
192	    }
193	
194	    /**
195	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
196	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
197	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
198	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
199	     */
200	    @Transient
201	    public Integer getCheckDigit() {
202	        if (this.customerCode == null) {
203	            return null;
204	        }
205	        int sum = 0;
206	        boolean dbl = true;
207	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
208	            char c = this.customerCode.charAt(i);
209	            if (c < '0' || c > '9') {
210	                continue;
211	            }
212	            int d = c - '0';
213	            if (dbl) {
214	                d *= 2;
215	                if (d > 9) {
216	                    d -= 9;
217	                }
218	            }
219	            sum += d;
220	            dbl = !dbl;
221	        }
222	        return (10 - (sum % 10)) % 10;
223	    }
