233	        boolean hasEmail = this.email != null && !this.email.isBlank();
234	        if (hasEmail) {
235	            level++;
236	        }
237	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
238	        if (unique) {
239	            level++;
240	        }
241	        return Math.min(level, 3);
