244	    /**
245	     * The owner's locality: the canonical region derived first from the postcode and only then from
246	     * the city. When the postcode is a 4-digit value within a known region range
247	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) that region is returned,
248	     * disambiguating cities that share a name. Otherwise, when the postcode is absent or in no known
249	     * range, the region is derived from the city via the fixed city-to-region table
250	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code 'UNKNOWN'} when
251	     * the city is not in the table.
252	     */
253	    @Transient
254	    public String getLocality() {
255	        String regionByPostcode = regionForPostcode(this.postcode);
256	        if (regionByPostcode != null) {
257	            return regionByPostcode;
258	        }
259	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
260	    }
261	
262	    /**
263	     * Resolve a region from a postcode by its known 4-digit range, or {@code null} when the postcode
264	     * is {@code null}, not exactly 4 digits, or falls in no known range.
265	     */
266	    private static String regionForPostcode(String postcode) {
267	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
268	            return null;
269	        }
270	        int value = Integer.parseInt(postcode);
271	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
272	            int[] range = entry.getValue();
273	            if (value >= range[0] && value <= range[1]) {
274	                return entry.getKey();
275	            }
276	        }
277	        return null;
278	    }
279	
280	    /**
281	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
282	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
283	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
284	     * owner has none), and the household id the stored shared identifier (empty when the owner is
285	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
286	     * are equal; because the telephone is part of the key, two members of the same household with
287	     * different telephones have different identity keys.
288	     */
289	    @Transient
290	    public String getIdentityKey() {
291	        String telephonePart = this.telephone == null ? "" : this.telephone;
292	        String emailPart = this.email == null ? "" : this.email;
293	        String householdPart = this.householdId == null ? "" : this.householdId;
