299	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
300	     */
301	    @Transient
302	    public String getContactPreference() {
303	        boolean hasEmail = this.email != null && !this.email.isBlank();
304	        return hasEmail ? "EMAIL" : "PHONE";
305	    }
306	
307	    protected Set<Pet> getPetsInternal() {
308	        if (this.pets == null) {
309	            this.pets = new HashSet<>();
310	        }
311	        return this.pets;
312	    }
313	
