325	        this.pets = new HashSet<>(pets);
326	    }
327	
328	    public void addPet(Pet pet) {
329	        getPetsInternal().add(pet);
330	        pet.setOwner(this);
331	    }
332	
333	    /**
334	     * Return the Pet with the given name, or null if none found for this Owner.
335	     *
336	     * @param name to test
337	     * @return true if pet name is already in use
338	     */
339	    public Pet getPet(String name) {
340	        return getPet(name, false);
341	    }
342	
343	    /**
344	     * Return the Pet with the given name, or null if none found for this Owner.
345	     *
346	     * @param name to test
347	     * @return true if pet name is already in use
348	     */
349	    public Pet getPet(String name, boolean ignoreNew) {
350	        name = name.toLowerCase();
351	        for (Pet pet : getPetsInternal()) {
352	            if (!ignoreNew || !pet.isNew()) {
353	                String compName = pet.getName();
354	                compName = compName.toLowerCase();
355	                if (compName.equals(name)) {
356	                    return pet;
357	                }
358	            }
359	        }
360	        return null;
361	    }
362	
363	    public Pet getPet(Integer petId) {
364	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
365	    }
366	
367	    @Override
368	    public String toString() {
369	        return new ToStringCreator(this)
370	
371	            .append("id", this.getId())
372	            .append("new", this.isNew())
373	            .append("lastName", this.getLastName())
374	            .append("firstName", this.getFirstName())
375	            .append("address", this.address)
376	            .append("city", this.city)
377	            .append("telephone", this.telephone)
378	            .toString();
379	    }
