117	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
118	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
119	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
120	     */
121	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
122	        "61", 9,
123	        "1", 10);
